  // ---------- Refresh-safe scanner queue persistence ----------
  function openQueueDb(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){resolve(null);return;}const req=indexedDB.open(QUEUE_DB_NAME,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(QUEUE_STORE))req.result.createObjectStore(QUEUE_STORE);};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
  async function queueImagePut(id,dataUrl){try{const db=await openQueueDb();if(!db)return false;await new Promise((resolve,reject)=>{const tx=db.transaction(QUEUE_STORE,'readwrite');tx.objectStore(QUEUE_STORE).put(dataUrl,String(id));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();return true;}catch(_){return false;}}
  async function queueImageGet(id){try{const db=await openQueueDb();if(!db)return null;const value=await new Promise((resolve,reject)=>{const tx=db.transaction(QUEUE_STORE,'readonly'),req=tx.objectStore(QUEUE_STORE).get(String(id));req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error);});db.close();return value;}catch(_){return null;}}
  async function queueImageDelete(id){try{const db=await openQueueDb();if(!db)return;await new Promise((resolve,reject)=>{const tx=db.transaction(QUEUE_STORE,'readwrite');tx.objectStore(QUEUE_STORE).delete(String(id));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();}catch(_){/* best effort */}}
  function serialiseQueueItem(item){const {dataUrl,...rest}=item;return{...rest,imageStored:!!item.imageStored};}
  async function persistScanQueueState(){try{const current=currentQueueItem?.();await S.setJSON(SCAN_QUEUE_META_KEY,{version:1,seq:state.scanQueueSeq,reviewId:current?.id||null,items:state.scanQueue.map(serialiseQueueItem),savedAt:Date.now()});}catch(_){/* queue persistence is best effort */}}
  function schedulePersistScanQueue(){clearTimeout(schedulePersistScanQueue.t);schedulePersistScanQueue.t=setTimeout(()=>persistScanQueueState(),40);}
  async function restoreScanQueueState(){const saved=await S.getJSON(SCAN_QUEUE_META_KEY,null);if(!saved?.items?.length)return;const rows=[];for(const raw of saved.items){const item={...raw,dataUrl:null,nextRetryAt:0};if(item.imageStored)item.dataUrl=await queueImageGet(item.id);if(['scanning','fallback','waiting'].includes(item.status)&&item.dataUrl){item.status='error';item.error='A previous scan was interrupted. Tap Retry Scan when you want to try again.';item.statusText='NEEDS RETRY · previous request stopped';}if(!item.manual&&!item.dataUrl&&item.status!=='saved'){item.status='error';item.statusText='NEEDS RETRY · screenshot could not be restored';item.error='The queued screenshot could not be restored. Remove it and add the screenshot again.';}rows.push(item);}state.scanQueue=rows;state.scanQueueSeq=Math.max(Number(saved.seq)||0,...rows.map(x=>Number(x.id)||0),0);const reviewIndex=rows.findIndex(x=>x.id===saved.reviewId&&['ready','saved'].includes(x.status));state.scanQueueReviewIndex=reviewIndex;renderScanQueue();if(reviewIndex>=0)loadQueueReview(reviewIndex);if(rows.some(x=>x.status==='queued'))runScanQueue();}

  // ---------- Scanner v9 · Gemini 3.1 Flash Live · exact-reference batch review queue ----------
  let scannerHealthOkAt=0;
  const SCANNER_HEALTH_TTL_MS=5*60*1000;
  function scannerSetupFailure(err){return ['NOT_CONFIGURED','REFERENCE_LOAD','NETWORK','GEMINI_API_ERROR','GEMINI_LIVE_ERROR','GEMINI_LIVE_CLOSED'].includes(String(err?.code||''));}
  function scannerSetupMessage(err){
    if(err?.code==='NOT_CONFIGURED')return 'Gemini API key is not saved on this device. Open More → Settings → Gemini Scanner, paste the key, then Test Connection.';
    if(err?.code==='REFERENCE_LOAD')return `Scanner reference files could not be loaded: ${err.message||'reference load failed'}`;
    if(err?.code==='NETWORK')return `Gemini could not be reached from this device: ${err.message||'network error'}`;
    return err?.message||'Gemini Flash Live setup failed.';
  }
  function pauseQueueForScannerSetup(err){
    const message=scannerSetupMessage(err),code=String(err?.code||'SCANNER_SETUP');
    state.scanQueue.forEach(item=>{
      if(item.manual||!['queued','scanning'].includes(item.status))return;
      item.status='waiting';item.error=message;item.statusText='SCANNER SETUP REQUIRED';item.setupBlocked=true;item.setupErrorCode=code;item.nextRetryAt=0;
    });
    progress({progress:0,label:message});renderScanQueue();schedulePersistScanQueue();toast(message,'err');
  }
  function resumeSetupBlockedQueue(){
    let resumed=0;
    state.scanQueue.forEach(item=>{if(item.setupBlocked&&item.status==='waiting'&&item.dataUrl){item.status='queued';item.statusText='QUEUED · scanner connection restored';item.error='';item.setupBlocked=false;item.setupErrorCode='';resumed++;}});
    if(resumed){renderScanQueue();schedulePersistScanQueue();runScanQueue();}
    return resumed;
  }
  async function ensureScannerQueueHealth(){
    const key=await SC.getApiKey();
    if(!key){const e=new Error('Gemini Scanner is not configured on this device.');e.code='NOT_CONFIGURED';throw e;}
    if(Date.now()-scannerHealthOkAt<SCANNER_HEALTH_TTL_MS)return true;
    progress({progress:.01,label:'Checking Gemini 3.1 Flash Live connection…'});
    await SC.health();scannerHealthOkAt=Date.now();return true;
  }
  function resetScanner(){state.scan=null;state.scanAbilities=[];state.scanRelatedRoles=[];state.scanDuplicateKey='';state.scanPreservedRoles=[];state.scanManualVerified=false;state.scanQueueReviewIndex=-1;if($('#scanReview'))$('#scanReview').style.display='none';if($('#scanPreview'))$('#scanPreview').removeAttribute('src');$('#scanWindow')?.classList.remove('has-image','scanning');if($('#scanProgressBar'))$('#scanProgressBar').style.width='0%';if($('#scanProgressText'))$('#scanProgressText').textContent='Choose one or more player screenshots';if($('#scanPercent'))$('#scanPercent').textContent='0%';}
  function clearScannerReview(){state.scan=null;state.scanAbilities=[];state.scanRelatedRoles=[];state.scanPreservedRoles=[];state.scanDuplicateKey='';state.scanManualVerified=false;state.scanQueueReviewIndex=-1;$('#scanReview').style.display='none';$('#scanSaveNote').textContent='';if($('#scanManualVerified'))$('#scanManualVerified').checked=false;if($('#scanManualVerify'))$('#scanManualVerify').style.display='none';updateQueueReviewButtons();renderScanQueue();schedulePersistScanQueue();}
  function progress(p){const pct=Math.round((p.progress||0)*100);$('#scanProgressBar').style.width=pct+'%';$('#scanProgressText').textContent=p.label||'Scanning';$('#scanPercent').textContent=pct+'%';}
  const fileToDataUrl=file=>new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file);});
  function playstyleTierValue(){return Number($('#scanPlaystyleLevel')?.value)||0;}
  function currentQueueItem(){return state.scanQueueReviewIndex>=0?state.scanQueue[state.scanQueueReviewIndex]||null:null;}
  function queueStatusLabel(item){const labels={queued:'QUEUED',scanning:'SCANNING',fallback:'NEEDS RETRY',waiting:'NEEDS RETRY',ready:'READY TO REVIEW',saved:'SAVED',error:'NEEDS RETRY',failed:'SCAN FAILED'};return labels[item.status]||String(item.status||'').toUpperCase();}
  function renderScanQueue(){
    const el=$('#scanQueue');if(!el)return;
    if(!state.scanQueue.length){el.innerHTML='';return;}
    const counts={queued:0,scanning:0,ready:0,saved:0,error:0,failed:0};state.scanQueue.forEach(x=>counts[x.status]=(counts[x.status]||0)+1);
    const retryCount=(counts.error||0)+(counts.failed||0)+(counts.waiting||0)+(counts.fallback||0);
    el.innerHTML=`<div class="scan-queue-summary"><span>${state.scanQueue.length} player${state.scanQueue.length===1?'':'s'} in queue</span><span>${counts.ready} ready · ${counts.saved} saved${retryCount?` · ${retryCount} retry`:''}</span></div>`+state.scanQueue.map((item,i)=>{const detail=['error','failed','waiting','fallback'].includes(item.status)?(item.error||item.statusText||queueStatusLabel(item)):(item.statusText||item.error||queueStatusLabel(item));const canOpen=item.status==='ready'||item.status==='saved';const canRetry=['error','failed','waiting','fallback'].includes(item.status);return `<div class="scan-queue-row ${esc(item.status)} ${i===state.scanQueueReviewIndex?'reviewing':''}" ${canOpen?`data-queue-open="${i}" role="button" tabindex="0"`:''}><span class="queue-no">${i+1}</span><span class="queue-copy"><b>${esc(item.scan?.name||item.fileName||'Manual player')}</b><small>${esc(detail)}</small></span><span><span class="queue-state">${esc(queueStatusLabel(item))}</span>${canRetry?`<button type="button" class="scan-queue-retry" data-queue-retry="${i}">Retry Scan</button>`:''}<button type="button" class="scan-queue-remove" data-queue-remove="${i}" aria-label="Remove from queue">×</button></span></div>`}).join('');
  }
  function reviewableIndices(){return state.scanQueue.map((x,i)=>x.status==='ready'?i:-1).filter(i=>i>=0);}
  function persistCurrentQueueDraft(){
    const item=currentQueueItem();if(!item||!state.scan||item.status==='saved')return;
    item.reviewState={name:$('#scanName')?.value??'',age:$('#scanAge')?.value??'',ovr:$('#scanOvr')?.value??'',roles:[$('#scanRole')?.value,$('#scanRole2')?.value,$('#scanRole3')?.value].filter(Boolean),relatedRoles:[...state.scanRelatedRoles],playstyleName:$('#scanPlaystyle')?.value||'',playstyleLevel:playstyleTierValue(),abilities:[...state.scanAbilities],manualVerified:!!state.scanManualVerified};schedulePersistScanQueue();
  }
  function updateQueueReviewButtons(){
    const item=currentQueueItem(),ready=reviewableIndices(),hasOther=ready.some(i=>i!==state.scanQueueReviewIndex);
    const save=$('#saveScannedPlayer'),next=$('#nextQueuedPlayerBtn'),rescan=$('#rescanBtn');
    if(save)save.textContent=hasOther?'Save & Next':'Save Player';
    if(next){next.style.display=hasOther?'inline-flex':'none';next.disabled=!hasOther;}
    if(rescan){rescan.style.display=item&&!item.manual&&item.status==='ready'?'inline-flex':'none';rescan.disabled=!item||item.manual||item.status!=='ready';}
  }
  function scanRequiredSkills(scan=state.scan){return scan?.layout==='gk'?[...D.GK_SKILLS,...D.GK_PHYSICAL]:[...D.OUTFIELD_SKILLS];}
  function scanDataComplete(){if(!state.scan)return false;const req=scanRequiredSkills(),skills=state.scan.skills||{};return !!($('#scanName')?.value.trim()&&$('#scanRole')?.value&&Number.isFinite(Number($('#scanAge')?.value))&&Number.isFinite(Number($('#scanOvr')?.value))&&req.every(s=>Number.isFinite(Number(skills[s]))));}
  function renderScanConfidence(){
    const el=$('#scanConfidence');if(!el||!state.scan)return;
    if(state.scan.manualEntry){el.innerHTML='<span class="chip manual-mode-badge">Manual entry</span>';return;}
    const checks=Object.values(state.scan.checks||{}),all=checks.length>0&&checks.every(c=>c.ok),n=Math.round((state.scan.confidence?.overall||0)*100);
    if(state.scanManualVerified){el.innerHTML=`<span class="chip verified-badge">✓ Manually verified</span><span class="confidence-secondary">Gemini read score ${n}%</span>`;return;}
    if(all&&scanDataComplete()){el.innerHTML=`<span class="chip verified-badge">✓ Arithmetic checks passed</span><span class="confidence-secondary">Gemini read score ${n}%</span>`;return;}
    el.innerHTML=`<span class="chip active">Gemini read score ${n}%</span>`;
  }
  function renderAbilityPicker(){$('#abilityPicker').innerHTML=D.SPECIAL_ABILITIES.map(a=>`<button type="button" class="chip ${state.scanAbilities.includes(a)?'active':''}" data-ability="${esc(a)}">${esc(a)}</button>`).join('');}
  function renderScanRelated(){const natural=new Set([$('#scanRole')?.value,$('#scanRole2')?.value,$('#scanRole3')?.value].filter(Boolean));state.scanRelatedRoles=state.scanRelatedRoles.filter(r=>!natural.has(r));$('#scanRelatedPicker').innerHTML=D.ALL_POSITIONS.filter(r=>!natural.has(r)).map(r=>`<button type="button" class="chip ${state.scanRelatedRoles.includes(r)?'active':''}" data-scan-related="${r}">${r}</button>`).join('');}
  function renderDetectedRoles(){const el=$('#detectedRoles');if(!el||!state.scan)return;if(state.scan.manualEntry){el.innerHTML='<span class="chip manual-mode-badge">Manual player</span>';return;}const detected=(state.scan.roles||[]).filter(Boolean),primary=$('#scanRole')?.value||'';el.innerHTML=detected.length?detected.map(r=>`<button type="button" class="chip detected-role-chip ${r===primary?'active':''}" data-detected-primary-role="${esc(r)}">${esc(r)}${r===primary?' · primary':''}</button>`).join(''):'<span class="mini-note">Role needs review.</span>';}
  function refreshScanRoleDependentUi(){if(!state.scan)return;const roles=[$('#scanRole')?.value,$('#scanRole2')?.value,$('#scanRole3')?.value].filter(Boolean).filter((r,i,a)=>a.indexOf(r)===i);const selected=$('#scanPlaystyle')?.value||'';$('#scanPlaystyle').innerHTML=playstyleOptions(roles,selected);const has=!!$('#scanPlaystyle').value;$('#scanPlaystyleLevel').disabled=!has;state.scanRelatedRoles=state.scanRelatedRoles.filter(r=>!roles.includes(r));renderScanRelated();renderDetectedRoles();persistCurrentQueueDraft();refreshScanVerification();}
  function setDetectedPrimaryRole(role){if(!state.scan||state.scan.manualEntry)return;const detected=(state.scan.roles||[]).filter(Boolean),existing=[$('#scanRole')?.value,$('#scanRole2')?.value,$('#scanRole3')?.value].filter(Boolean),roles=[role,...detected,...existing].filter((r,i,a)=>r&&a.indexOf(r)===i).slice(0,3);if(state.scan.layout==='gk'&&role!=='GK')return;$('#scanRole').value=roles[0]||'';$('#scanRole2').value=roles[1]||'';$('#scanRole3').value=roles[2]||'';state.scan.position=roles[0]||state.scan.position;refreshScanRoleDependentUi();toast(`${role} set as primary role`);}
  function scrollToScanReview(){const el=$('#scanReviewPlayerCard');if(!el)return;requestAnimationFrame(()=>setTimeout(()=>el.scrollIntoView({behavior:'smooth',block:'start'}),40));}
  document.addEventListener('click',e=>{const dr=e.target.closest('[data-detected-primary-role]');if(dr){setDetectedPrimaryRole(dr.dataset.detectedPrimaryRole);return;}const b=e.target.closest('[data-ability]');if(b){const a=b.dataset.ability;if(state.scanAbilities.includes(a))state.scanAbilities=state.scanAbilities.filter(x=>x!==a);else state.scanAbilities.push(a);renderAbilityPicker();return;}const rr=e.target.closest('[data-scan-related]');if(rr){const r=rr.dataset.scanRelated;state.scanRelatedRoles=state.scanRelatedRoles.includes(r)?state.scanRelatedRoles.filter(x=>x!==r):[...state.scanRelatedRoles,r];renderScanRelated();}});
  function currentScanChecks(ovrValue){
    if(!state.scan)return{};const skills=state.scan.skills||{},totals=state.scan.raw?.totals||{},checks={};
    if(!state.scan.manualEntry){if(state.scan.layout==='gk'){checks.goalkeeping=SC.checkAggregate(D.GK_SKILLS.map(s=>Number(skills[s])),totals.att);checks.physical=SC.checkAggregate(D.GK_PHYSICAL.map(s=>Number(skills[s])),totals.phys);}else{checks.defence=SC.checkAggregate(D.GROUPS_OUTFIELD.Defence.map(s=>Number(skills[s])),totals.def);checks.attack=SC.checkAggregate(D.GROUPS_OUTFIELD.Attack.map(s=>Number(skills[s])),totals.att);checks.physical=SC.checkAggregate(D.GROUPS_OUTFIELD.Physical.map(s=>Number(skills[s])),totals.phys);}}
    const vals=Object.values(skills).map(Number).filter(Number.isFinite),avg=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:0,ovr=Number(ovrValue);checks.ovr={average:avg,error:Number.isFinite(ovr)&&vals.length?Math.abs(avg-ovr):null,ok:Number.isFinite(ovr)&&vals.length===scanRequiredSkills().length&&Math.abs(avg-ovr)<=1.5};return checks;
  }
  function scanUnresolved(checks){return Object.entries(checks||{}).filter(([,c])=>!c.ok);}
  function refreshScanVerification(){
    if(!state.scan)return true;const checks=currentScanChecks($('#scanOvr').value);state.scan.checks=checks;const unresolved=scanUnresolved(checks);state.scan.validation={resolved:unresolved.length===0,unresolvedChecks:unresolved.map(([name,c])=>({name,error:c.error,average:c.average}))};
    $('#scanChecks').innerHTML=Object.entries(checks).map(([name,c])=>`<div class="verify ${c.ok?'ok':'warn'}"><strong>${c.ok?'✓':'!'} ${esc(name)}</strong><span>${c.error==null?'Not enough data to verify':c.ok?`within display rounding · ${Number(c.error).toFixed(1)}`:`outside tolerance · ${Number(c.error).toFixed(1)}`}</span></div>`).join('');
    const manual=!!state.scanManualVerified,manualBox=$('#scanManualVerify');if(manualBox)manualBox.style.display=!state.scan.manualEntry&&unresolved.length?'block':'none';const save=$('#saveScannedPlayer');if(save)save.disabled=false;
    if(state.scan.manualEntry){const missing=scanRequiredSkills().filter(s=>!Number.isFinite(Number(state.scan.skills?.[s])));$('#scanSaveNote').innerHTML=missing.length?`<b>Manual entry.</b> Enter every visible skill value before saving. ${missing.length} skill${missing.length===1?'':'s'} remaining.`:'<b>Manual entry complete.</b> Review playstyle tier and every special ability, then save.';}
    else if(unresolved.length){const detail=unresolved.map(([name,c])=>`${name}${c.error==null?'':` (${Number(c.error).toFixed(1)} out)`}`).join(', ');$('#scanSaveNote').innerHTML=manual?`<b>Manual verification accepted.</b> Remaining scanner mismatch: ${esc(detail)}. Your reviewed values will be saved and marked as manually verified.`:`<b>Verification required.</b> Cross-check sees: ${esc(detail)}. Correct any wrong values. If the visible values match Top Eleven, tick <b>I checked the screenshot manually</b>.`;}
    else{$('#scanSaveNote').textContent='Arithmetic checks pass within Top Eleven whole-number display rounding. Review the scanned core data, playstyle level and Special Abilities before saving.';}
    renderScanConfidence();persistCurrentQueueDraft();return unresolved.length===0;
  }
  function renderScanSkills(scan){const groups=scan.layout==='gk'?D.GROUPS_GK:D.GROUPS_OUTFIELD;$('#scanSkills').innerHTML=Object.entries(groups).map(([g,names])=>`<div class="skill-group"><h3>${esc(g)}</h3><div class="skill-grid">${names.map(s=>`<label class="skill scan-skill"><span>${esc(s)}</span><input class="scan-skill-input" type="number" min="0" max="520" inputmode="numeric" data-scan-skill="${esc(s)}" value="${esc(scan.skills[s]??'')}"></label>`).join('')}</div></div>`).join('');}
  function populateScanReview(scan,review={}){
    state.scan=scan;state.scanDuplicateKey='';state.scanPreservedRoles=[];state.scanRelatedRoles=[...(review.relatedRoles||[])];state.scanAbilities=[...(review.abilities||scan.specialAbilities||[])];state.scanManualVerified=!!review.manualVerified;$('#scanReview').style.display='block';
    $('#scanName').value=review.name??scan.name??'';$('#scanAge').value=review.age??scan.age??'';$('#scanOvr').value=review.ovr??scan.ovr??'';const reviewRoles=review.roles||scan.roles||[];const allowed=scan.manualEntry?D.ALL_POSITIONS:(scan.layout==='gk'?['GK']:D.ALL_POSITIONS.filter(r=>r!=='GK'));const fill=(id,value,label)=>{$(id).innerHTML=`<option value="">${label}</option>`+allowed.map(r=>`<option value="${r}" ${r===value?'selected':''}>${r}</option>`).join('');};fill('#scanRole',reviewRoles[0]||scan.position,'Choose role');fill('#scanRole2',reviewRoles[1]||'','None');fill('#scanRole3',reviewRoles[2]||'','None');const primary=$('#scanRole').value;$('#scanRole2').disabled=primary==='GK';$('#scanRole3').disabled=primary==='GK';
    renderDetectedRoles();
    const detectedPs=scan.playstyle?.name||'',selectedPs=review.playstyleName??detectedPs;$('#scanPlaystyle').innerHTML=playstyleOptions(reviewRoles.length?reviewRoles:(scan.roles||[scan.position]),selectedPs);const level=review.playstyleLevel??scan.playstyle?.level??0;$('#scanPlaystyleLevel').innerHTML=playstyleLevelOptions(level,!!selectedPs);$('#scanPlaystyleLevel').disabled=!selectedPs;
    const visual=$('#scanDetectedVisuals');if(visual){const bits=[];if(detectedPs)bits.push(`<b>Playstyle:</b> ${esc(detectedPs)}${scan.playstyle?.levelName?` · ${esc(scan.playstyle.levelName)}`:''}`);if((scan.specialAbilities||[]).length)bits.push(`<b>Abilities:</b> ${esc(scan.specialAbilities.join(', '))}`);if(scan.raw?.specialAbilityTraining?.active)bits.push('<b>Ability training:</b> in progress — not unlocked yet');visual.innerHTML=(bits.length?bits.join('<br>'):'No playstyle or Special Ability was confidently detected.')+'<br><span>Review and correct any field before saving.</span>';}
    if($('#scanManualVerified'))$('#scanManualVerified').checked=state.scanManualVerified;renderScanRelated();renderAbilityPicker();renderScanSkills(scan);refreshScanVerification();updateQueueReviewButtons();renderScanQueue();
  }
  function loadQueueReview(index,{scroll=false}={}){
    if(index<0||index>=state.scanQueue.length)return;persistCurrentQueueDraft();const item=state.scanQueue[index];if(!['ready','saved'].includes(item.status))return;state.scanQueueReviewIndex=index;if(item.dataUrl){$('#scanPreview').src=item.dataUrl;$('#scanWindow').classList.add('has-image');}else{$('#scanPreview').removeAttribute('src');$('#scanWindow').classList.remove('has-image');}populateScanReview(item.scan,item.reviewState||{});$('#scanProgressText').textContent=item.status==='saved'?'Saved player':`Reviewing ${item.scan?.name||item.fileName||`player ${index+1}`}`;$('#scanPercent').textContent='100%';$('#scanProgressBar').style.width='100%';if(scroll||item.scrollOnReady){item.scrollOnReady=false;scrollToScanReview();}}
  function nextReadyIndex(from=state.scanQueueReviewIndex){const ready=reviewableIndices();if(!ready.length)return-1;const after=ready.find(i=>i>from);return after??ready[0];}
  function cancelScanForItem(itemId){
    const controller=scanControllers.get(Number(itemId));if(controller){controller.abort();scanControllers.delete(Number(itemId));}
  }
  async function runScanQueue(){
    if(state.scanQueueScanning)return;
    try{await ensureScannerQueueHealth();}catch(err){pauseQueueForScannerSetup(err);return;}
    state.scanQueueScanning=true;renderScanQueue();schedulePersistScanQueue();
    try{
      while(true){
        const idx=state.scanQueue.findIndex(x=>x.status==='queued');if(idx<0)break;const item=state.scanQueue[idx];
        if(!item.dataUrl&&item.imageStored)item.dataUrl=await queueImageGet(item.id);
        if(!item.dataUrl){item.status='failed';item.error='Queued screenshot is unavailable. Remove it and add the screenshot again.';item.statusText='SCAN FAILED · screenshot unavailable';renderScanQueue();schedulePersistScanQueue();continue;}
        item.status='scanning';item.error='';item.statusText='SCANNING · core + playstyle + abilities';item.autoAttempts=Math.max(0,Number(item.autoAttempts||0))+1;item.lastAttemptAt=Date.now();item.nextRetryAt=0;renderScanQueue();schedulePersistScanQueue();
        $('#scanPreview').src=item.dataUrl;$('#scanWindow').classList.add('has-image','scanning');
        const controller=new AbortController();scanControllers.set(Number(item.id),controller);
        try{
          const scan=await SC.scan(item.dataUrl,p=>{
            item.status='scanning';item.statusText=p.label||'SCANNING';
            progress({progress:p.progress||0,label:`Player ${idx+1}/${state.scanQueue.length} · ${p.label||'Scanning'}`});renderScanQueue();schedulePersistScanQueue();
          },{signal:controller.signal});
          if(controller.signal.aborted)continue;
          item.scan=scan;item.status='ready';item.statusText=`READY TO REVIEW · ${String(scan.raw?.model||scan.model||'Gemini').replace(/^gemini-/,'')} · visuals detected`;item.fileName=scan.name||item.fileName;item.nextRetryAt=0;item.error='';renderScanQueue();schedulePersistScanQueue();
        }catch(err){
          if(err?.code==='SCAN_CANCELLED'){item.status='error';item.error='Scan cancelled. Tap Retry Scan when you want to run it again.';item.statusText='NEEDS RETRY · scan cancelled';}
          else if(scannerSetupFailure(err)){
            item.status='queued';
            pauseQueueForScannerSetup(err);
            break;
          }else{
            item.status='failed';item.nextRetryAt=0;item.error=err?.message||'Scan failed';item.statusText=err?.kind==='quota_daily'?'SCAN FAILED · free quota exhausted':'SCAN FAILED';
          }
          renderScanQueue();schedulePersistScanQueue();
        }finally{
          if(scanControllers.get(Number(item.id))===controller)scanControllers.delete(Number(item.id));
          $('#scanWindow').classList.remove('scanning');
        }
        // Process the next queued player. Failed scans stay stopped until the user explicitly retries them.
      }
    }finally{
      state.scanQueueScanning=false;renderScanQueue();schedulePersistScanQueue();
      if(state.scanQueueReviewIndex<0){const first=reviewableIndices()[0];if(first!=null)loadQueueReview(first);}
      const ready=reviewableIndices().length,pending=state.scanQueue.filter(x=>x.status==='queued'||x.status==='scanning').length,failed=state.scanQueue.filter(x=>['error','failed'].includes(x.status)).length;
      if(ready)progress({progress:1,label:`Queue ready · ${ready} player${ready===1?'':'s'} to review${failed?` · ${failed} need retry`:''}`});
      else if(!pending&&failed)progress({progress:1,label:`Queue stopped · ${failed} scan${failed===1?'':'s'} need Retry Scan`});
      else if(!pending)progress({progress:1,label:'Queue finished'});
    }
  }
  async function addFilesToQueue(files){
    const list=[...files].filter(f=>f.type?.startsWith('image/')||/\.(png|jpe?g|webp)$/i.test(f.name));if(!list.length)return;
    for(let fileIndex=0;fileIndex<list.length;fileIndex++){const file=list[fileIndex],dataUrl=await fileToDataUrl(file),id=++state.scanQueueSeq,updateKey=fileIndex===0?state.scanUpdateKey||'':'';const imageStored=await queueImagePut(id,dataUrl);state.scanQueue.push({id,fileName:file.name,dataUrl,status:'queued',statusText:updateKey?'QUEUED · update existing player':'QUEUED',scan:null,error:'',manual:false,reviewState:null,imageStored,autoAttempts:0,nextRetryAt:0,updateKey});}state.scanUpdateKey='';
    $('#scanFile').value='';renderScanQueue();schedulePersistScanQueue();toast(`${list.length} screenshot${list.length===1?'':'s'} added to scan queue`);runScanQueue();
  }
