  document.addEventListener('click',async e=>{const open=e.target.closest('[data-queue-open]');if(open&&!e.target.closest('[data-queue-remove]')){const i=Number(open.dataset.queueOpen);if(Number.isInteger(i))loadQueueReview(i,{scroll:true});return;}const retry=e.target.closest('[data-queue-retry]');if(retry){e.stopPropagation();const i=Number(retry.dataset.queueRetry),item=state.scanQueue[i];if(item){cancelScanForItem(item.id);item.status='queued';item.statusText='QUEUED · Retry Scan requested';item.error='';item.scan=null;item.reviewState=null;item.autoAttempts=0;item.nextRetryAt=0;item.setupBlocked=false;item.setupErrorCode='';renderScanQueue();schedulePersistScanQueue();runScanQueue();}return;}const remove=e.target.closest('[data-queue-remove]');if(remove){e.stopPropagation();const i=Number(remove.dataset.queueRemove);if(!Number.isInteger(i)||!state.scanQueue[i])return;const removed=state.scanQueue[i],wasCurrent=i===state.scanQueueReviewIndex;cancelScanForItem(removed.id);state.scanQueue.splice(i,1);await queueImageDelete(removed.id);if(state.scanQueueReviewIndex>i)state.scanQueueReviewIndex--;else if(wasCurrent)clearScannerReview();renderScanQueue();schedulePersistScanQueue();if(wasCurrent){const n=reviewableIndices()[0];if(n!=null)loadQueueReview(n,{scroll:true});}return;}});
