  function scanFormData(){const name=$('#scanName').value.trim(),age=Number($('#scanAge').value),ovr=Number($('#scanOvr').value),position=$('#scanRole').value,roles=[position,$('#scanRole2').value,$('#scanRole3').value].filter((r,i,a)=>r&&a.indexOf(r)===i),relatedRoles=state.scanRelatedRoles.filter(r=>!roles.includes(r));return{name,age,ovr,position,roles,relatedRoles};}
  function validateScanForm(x){if(!state.scan)return'No player loaded';if(!x.name||!x.position)return'Check the name and primary role before saving';if(!Number.isFinite(x.age)||x.age<15||x.age>60)return'Check the player age before saving';if(!Number.isFinite(x.ovr)||x.ovr<1||x.ovr>520)return'Check the OVR before saving';if(!state.scan.manualEntry&&state.scan.layout==='gk'&&x.roles.some(r=>r!=='GK'))return'GK scans can only be saved as GK';if(!state.scan.manualEntry&&state.scan.layout!=='gk'&&x.roles.includes('GK'))return'Outfield scans cannot be saved as GK';const missing=scanRequiredSkills().filter(s=>!Number.isFinite(Number(state.scan.skills?.[s])));if(missing.length)return`Enter all ${scanRequiredSkills().length} skill values before saving (${missing.length} missing)`;refreshScanVerification();return'';}
  async function saveScanToKey(key=null){
    const x=scanFormData(),err=validateScanForm(x);if(err){toast(err,'err');return false;}const unresolved=scanUnresolved(state.scan?.checks||{});if(unresolved.length&&!state.scan.manualEntry&&!state.scanManualVerified){const detail=unresolved.map(([name,c])=>`${name}${c.error==null?'':` (${Number(c.error).toFixed(1)} out)`}`).join(', ');const accepted=window.confirm(`Scanner verification still reports: ${detail}.\n\nIf you checked the screenshot and the visible values are correct, press OK to save them as manually verified.`);if(!accepted)return false;state.scanManualVerified=true;if($('#scanManualVerified'))$('#scanManualVerified').checked=true;refreshScanVerification();}
    const existing=key?await P.get(key):null;let roles=x.roles;if(existing)roles=P.mergeVisibleNaturalRoles(P.normaliseRoles(existing),x.roles,3);const relatedRoles=state.scanRelatedRoles.length?[...x.relatedRoles]:(existing?.relatedRoles||x.relatedRoles);const selectedPlaystyle=$('#scanPlaystyle').value,selectedLevel=playstyleTierValue();let playstyle=existing?P.mergePlaystyleState(existing.playstyle,selectedPlaystyle||P.playstyleName(existing)):P.mergePlaystyleState(null,selectedPlaystyle);if(selectedPlaystyle&&selectedLevel>=1)playstyle={...playstyle,level:selectedLevel};
    await P.save({...existing,...x,position:roles[0]||x.position,roles,relatedRoles,skills:state.scan.skills,playstyle,specialAbilities:[...state.scanAbilities],specialAbilityTraining:state.scan.raw?.specialAbilityTraining||existing?.specialAbilityTraining||null,scanner:{version:SC.VERSION,provider:state.scan.provider||'manual-entry',model:state.scan.raw?.model||null,confidence:state.scan.confidence,checks:state.scan.checks,validation:{...state.scan.validation,manualVerified:!!state.scanManualVerified||!!state.scan.manualEntry,manualEntry:!!state.scan.manualEntry}}},key);return true;
  }
  async function completeQueueSave(name){
    const item=currentQueueItem(),removedIndex=state.scanQueueReviewIndex;
    if(item){cancelScanForItem(item.id);state.scanQueue.splice(removedIndex,1);if(item.imageStored)await queueImageDelete(item.id);}
    state.scanQueueReviewIndex=-1;state.scan=null;state.scanAbilities=[];state.scanRelatedRoles=[];state.scanPreservedRoles=[];state.scanDuplicateKey='';state.scanManualVerified=false;
    if($('#scanReview'))$('#scanReview').style.display='none';
    await renderDashboard();renderScanQueue();schedulePersistScanQueue();
    const n=reviewableIndices()[0];
    if(n!=null&&n>=0&&state.scanQueue[n]?.status==='ready'){loadQueueReview(n,{scroll:true});toast(`${name} saved · removed from queue · next player ready`);return;}
    const queued=state.scanQueue.filter(x=>['queued','scanning','fallback','waiting'].includes(x.status)).length,failed=state.scanQueue.filter(x=>x.status==='error'||x.status==='failed').length;
    $('#scanProgressBar').style.width='100%';$('#scanPercent').textContent='100%';
    if(queued){$('#scanProgressText').textContent=`${name} saved · removed from queue · ${queued} scan${queued===1?'':'s'} still queued/retrying`;toast(`${name} saved · removed from queue`);}
    else if(failed){$('#scanProgressText').textContent=`${name} saved · removed from queue · ${failed} player${failed===1?'':'s'} need retry`;toast(`${name} saved · ${failed} need retry`,'err');}
    else{$('#scanProgressText').textContent='Review queue complete';toast(`${name} saved · removed from queue`);}
  }
