  function masterProjectionHtml(r){const usage=Object.entries(r.meta?.masterUsage||{}).filter(([,n])=>Number(n)>0);if(!usage.length)return'';return `<div class="master-projection wide"><span>Master stock ${r.completed?'remaining':'projection'}</span><div>${usage.map(([id,n])=>{const name=D.MASTER_CAMPUS_DRILLS.find(d=>d.drillId===id)?.name||id,used=Number(n)||0,remaining=Number(r.meta?.remainingMasterStock?.[id]??0),owned=remaining+used;return `<section><b>${esc(name)}</b><small>${owned} owned at build</small><strong>${used} used</strong><em>${remaining} ${r.completed?'remaining now':'projected remaining'}</em></section>`;}).join('')}</div></div>`;}
  function renderSession(){const r=state.session;if(!r)return;$('#trainingResults').style.display='block';const priority=(r.meta?.priorityAttributes||[]);$('#priorityAttributes').innerHTML=priority.map((x,i)=>`<div class="priority-pill"><span>${i+1}</span><b>${esc(x.attribute)}</b><small>${esc(x.value)}</small></div>`).join('');const masterSeen={};$('#sessionList').innerHTML=r.drills?.length?r.drills.map((d,i)=>{let stockLine='';if(d.isMaster){masterSeen[d.drillId]=(masterSeen[d.drillId]||0)+1;const used=Number(r.meta?.masterUsage?.[d.drillId]||0),remaining=Number(r.meta?.remainingMasterStock?.[d.drillId]??0),owned=remaining+used;stockLine=`<div class="master-use-line">Card ${masterSeen[d.drillId]}/${used} · ${owned} owned · ${remaining} ${r.completed?'remaining':'left after this session'}</div>`;}const grey=(d.greyApplicableAttributes||[]);const greyLine=grey.length?`<div class="grey-info"><span>Grey / information only · zero score</span>${grey.map(a=>`<i>${esc(a)}</i>`).join('')}</div>`:'';return `<div class="drill-row ${d.isMaster?'master':''}"><div class="slot-no">${String(i+1).padStart(2,'0')}</div><img src="${drillAsset(d.name,d.cat)}"><div class="drill-copy"><div class="drill-title-line"><b>${esc(d.name)}</b>${d.isMaster?'<span class="master-badge small">MASTER</span>':''}</div><small>${d.isMaster?`+${d.effectPct}% Training Effect`:`${esc(d.levelName)} · +${d.effectPct}%`} · ${fmt(d.conditionDrop,2)}% condition · +${esc(d.xpPerPlayer)} XP</small>${stockLine}<div class="target-line"><span>Targets · ${d.targetedWhiteAttributes.length} white</span>${d.targetedWhiteAttributes.map(a=>`<i>${esc(a)}</i>`).join('')}</div>${greyLine}</div><span class="diff ${diffClass(d.diff)}">${esc(d.diff)}</span></div>`;}).join(''):'<div class="empty"><b>No legal session</b>Check My Drills and the selected player profile.</div>';$('#sessionSummary').innerHTML=`<div><span>Total condition</span><b>${fmt(r.meta?.totalCondition,2)}%</b></div><div><span>Total XP</span><b>${fmt(r.meta?.totalXp,0)}</b></div><div><span>Recommendation score</span><b>${fmt(r.meta?.totalUsefulScore,1)}</b></div>${masterProjectionHtml(r)}<p><strong>Top Eleven Tool calculation.</strong> The recommendation score rewards real drill strength and coverage of current white/key needs. Grey attributes have zero utility. It is not an exact predicted +X% gain.</p>`;$('#completeSessionBtn').disabled=!!r.completed;$('#completeSessionBtn').textContent=r.completed?'Session Completed ✓':'Mark Session Completed';$('#sessionCompleteNote').textContent=r.completed?(r.stockDeducted?'Master card stock has been deducted once; the remaining figures above are current.':'Completed. No Master cards were used.'):'Master figures above are projected only. Stock changes when you complete the whole session.';}
  $('#completeSessionBtn')?.addEventListener('click',async()=>{if(!state.session||state.session.completed)return;const usage=state.session.meta?.masterUsage||{};if(Object.values(usage).some(n=>Number(n)>0)&&!state.session.stockDeducted){const updatedMaster=await DP.deductMasterUsage(usage);state.session.stockDeducted=true;if(state.session.sourceSnapshot)state.session.sourceSnapshot.masterUpdatedAt=String(updatedMaster.updatedAt||'');}state.session.completed=true;state.session.completedAt=new Date().toISOString();await persistTraining();renderSession();await updateTrainingIntel();toast('Training session completed');});

