  const SET_PIECES_KEY='teamplan:setpieces:v4',LEGACY_SET_PIECES_V3_KEY='teamplan:setpieces:v3',LEGACY_SET_PIECES_V2_KEY='teamplan:setpieces:v2',MENTOR_STATE_KEY='mentor:state:v2',UI_RESTRUCTURE_KEY='migration:ui:v045';
