  async function loadMentorState(){let stateMap=await S.getJSON(MENTOR_STATE_KEY,null);if(!stateMap||typeof stateMap!=='object'){stateMap=Object.fromEntries(B.MENTORS.map(m=>[m.id,{unlocked:false,level:1}]));await S.setJSON(MENTOR_STATE_KEY,stateMap);}for(const m of B.MENTORS){const row=stateMap[m.id]||{};stateMap[m.id]={unlocked:!!row.unlocked,level:Math.max(1,Math.min(10,Math.round(Number(row.level)||1)))}}M.setStateOverrides(stateMap);return stateMap;}
