  async function setMentorLevel(id,value){const stateMap=await loadMentorState(),level=Math.max(1,Math.min(10,Math.round(Number(value)||1)));stateMap[id]={...(stateMap[id]||{unlocked:false}),level};await saveMentorState(stateMap);return level;}
