  async function showTeamPlanEmpty(players){const count=players.length,needed=Math.max(0,11-count),empty=$('#formationEmpty');clearPitch();clearPitch($('#setPiecePitch'));$('#formationName').textContent=count?'Squad incomplete':'No squad yet';$('#formationSummary').textContent=count?`Add ${needed} more player${needed===1?'':'s'} with complete attributes.`:'Add players to unlock Team Plan.';if(empty){empty.style.display='grid';empty.innerHTML=`<img src="assets/icons/squad.svg" alt=""><b>${count}/11 PLAYERS</b><span>${count?`${needed} more required for a full XI.`:'Build your squad before choosing a team plan.'}</span><button class="btn primary compact" data-go="add-player">+ Add Player</button>`;}if($('#setPieceEmpty'))$('#setPieceEmpty').style.display='grid';if($('#setPiecePicker'))$('#setPiecePicker').style.display='none';if($('#tacticPlan'))$('#tacticPlan').innerHTML='<div class="empty">Build a complete XI first.</div>';if($('#mentorStrip'))$('#mentorStrip').innerHTML='';if($('#mentorLevels'))$('#mentorLevels').innerHTML='';if($('#mentorReason'))$('#mentorReason').textContent='';currentTeamPlan=null;}
  async function renderFormationFromPlan(plan){const players=await P.all();if(!plan||plan.error){await showTeamPlanEmpty(players);if(plan?.error)$('#formationSummary').textContent=plan.error;return;}currentTeamPlan=plan;const empty=$('#formationEmpty');if(empty)empty.style.display='none';$('#formationName').textContent=plan.formationName;const naturalCount=plan.starters.filter(x=>x.suitability==='NATURAL').length;$('#formationSummary').textContent=`${naturalCount}/11 natural assignments · formation chosen automatically from your squad.`;clearPitch();for(const s0 of plan.starters){const p=await P.get(s0.playerKey);if(!p)continue;const el=document.createElement('button');el.className='pitch-player';el.style.left=(s0.y/10)+'%';el.style.top=((1-s0.x/1000)*100)+'%';el.dataset.playerKey=p.key;el.dataset.assignedRole=s0.assignedRole;const last=String(p.name||'Player').trim().split(/\s+/).pop();el.innerHTML=`<span class="pitch-player-ring"><img src="${roleAsset(s0.assignedRole)}"></span><b>${esc(last)}</b><small>${esc(s0.assignedRole)} · ${fmt(s0.roleMean,1)}</small>`;$('#formationPitch').appendChild(el);} }
  async function starterPlayers(plan){const out=[];for(const s0 of plan?.starters||[]){const p=await P.get(s0.playerKey);if(p)out.push(p);}return out;}
