    for(const [key,label] of SET_PIECE_MODES){const xy=SET_PIECE_LAYOUT[key]||[50,50],playerKey=assignments[key],p=playerKey?await P.get(playerKey):null;const el=document.createElement('button');el.className=`set-piece-slot ${state.setPieceMode===key?'active':''} ${p?'assigned':'empty'}`;el.style.left=xy[0]+'%';el.style.top=xy[1]+'%';el.dataset.setPieceMode=key;const last=p?String(p.name||'Player').trim().split(/\s+/).pop():'Add Player';el.innerHTML=`<span class="set-piece-slot-no">${key.startsWith('penalty')&&key!=='penalty1'?esc(key.replace('penalty','')):''}</span><span class="pitch-player-ring">${p?`<img src="${roleAsset(p.position||P.normaliseRoles(p)[0])}">`:'+'}</span><span class="set-piece-slot-copy"><small>${esc(label)}</small><b>${esc(last)}</b></span>`;pitch.appendChild(el);}
    await renderSetPieceCandidates(plan,assignments);const source=currentSetPieceState?.sources?.[state.setPieceMode]||'manual';$('#setPieceNote').textContent=state.setPieceMode==='captain'&&!assignments.captain?'Captain is a manual choice for now — no authoritative Top Eleven captain-selection formula has been recovered.':source==='auto'?`${setPieceLabel(state.setPieceMode)} is a Top Eleven Tool recommendation. Choose another player to make a manual override.`:source==='legacy'?`${setPieceLabel(state.setPieceMode)} is a saved pre-v0.5.0 choice. Use Refresh Recommendations to replace old generated picks, or choose a player to keep a manual override.`:`${setPieceLabel(state.setPieceMode)} is manually assigned. Your choice will be preserved when recommendations refresh.`;
