  function renderTacticsFromPlan(plan){const t=plan?.tactics,el=$('#tacticPlan');if(!el)return;if(!t){el.innerHTML='<div class="empty">Build the XI first.</div>';return;}const phase=TACTIC_PHASES[state.tacticPhase]||TACTIC_PHASES.possession;$('#tacticPhaseTitle').textContent=phase.title;el.innerHTML=phase.dims.map(dim=>{const o=TAC.option(dim,t.values[dim]);return `<div class="tactic-choice-card"><span>${esc(TACTIC_LABELS[dim])}</span><b>${esc(o?.label||t.values[dim])}</b></div>`;}).join('');$('#planDrainBadge').textContent=`${t.drainClass} drain`;$('#planDrainBadge').classList.add('active');$('#tacticFitNote').textContent='Built from your XI, exact condition drain and evidence-backed tactic semantics. Approach sets Mentality; it does not secretly weight every other setting.';}
  async function renderMentorFromPlan(plan){const r=plan?.mentor,stateMap=await loadMentorState(),best=r?.best?.mentor||null;if(best){$('#mentorStrip').innerHTML=`<div class="mentor active mentor-best"><img src="assets/mentors/${best.asset}"><div class="mentor-copy"><span>Recommended</span><b>${esc(best.displayName)}</b><small>${esc(best.title)} · Level ${esc(best.level)}</small></div></div>`;$('#mentorReason').textContent='Recommendation uses only Mentors you mark as unlocked. Tactical unlocks at Level 1, Attribute at Level 5 and Signature at Level 10. Exact per-level magnitudes remain unresolved unless captured.';}else{$('#mentorStrip').innerHTML='<div class="empty">No unlocked Mentor configured.</div>';$('#mentorReason').textContent='Mentors start Locked in this companion until you mark the ones you own as unlocked. This is user state, not a claim about every Top Eleven account.';}$('#mentorLevels').innerHTML=B.MENTORS.map(m=>{const st=stateMap[m.id]||{unlocked:false,level:1};return `<div class="mentor-level-row ${st.unlocked?'':'mentor-locked'}"><img src="assets/mentors/${m.asset}"><div><b>${esc(m.displayName)}</b><small>${esc(m.title)} · ${st.unlocked?`Level ${esc(st.level)}`:'Locked'}</small></div><div class="mentor-state-control"><label class="unlock-control" title="I have this Mentor unlocked"><input type="checkbox" data-mentor-unlocked="${esc(m.id)}" ${st.unlocked?'checked':''}><i></i></label><div class="mentor-level-control"><button type="button" data-mentor-step="-1" data-mentor-id="${esc(m.id)}" ${st.unlocked?'':'disabled'}>−</button><input type="number" min="1" max="10" inputmode="numeric" data-mentor-level="${esc(m.id)}" value="${esc(st.level)}" ${st.unlocked?'':'disabled'}><button type="button" data-mentor-step="1" data-mentor-id="${esc(m.id)}" ${st.unlocked?'':'disabled'}>+</button></div></div></div>`;}).join('');}
  async function renderTeamPlan(){const players=await P.all();setTeamPlanTab(state.teamPlanTab);setTacticPhase(state.tacticPhase);if(players.length<11){await showTeamPlanEmpty(players);return;}let plan=await TP.getOrBuild({templateId:null,mode:'bestXI',minCondition:60});if(plan.error){await showTeamPlanEmpty(players);return;}if($('#planApproach'))$('#planApproach').value=plan.approach||state.approach;if($('#planDrain'))$('#planDrain').value=plan.drainLimit||state.drainLimit;if(!plan.tactics)plan=await TP.updateRecommendations({approach:$('#planApproach')?.value||state.approach,drainLimit:$('#planDrain')?.value||state.drainLimit});currentTeamPlan=plan;await renderFormationFromPlan(plan);renderTacticsFromPlan(plan);await renderMentorFromPlan(plan);await renderSetPieces(plan);setTeamPlanTab(state.teamPlanTab);setTacticPhase(state.tacticPhase);}
