  document.addEventListener('click',async e=>{const tab=e.target.closest('[data-team-plan-tab]');if(tab){setTeamPlanTab(tab.dataset.teamPlanTab);return;}const phase=e.target.closest('[data-tactic-phase]');if(phase){setTacticPhase(phase.dataset.tacticPhase);return;}const mode=e.target.closest('[data-set-piece-mode]');if(mode){state.setPieceMode=mode.dataset.setPieceMode;persistUiState();if(currentTeamPlan)await renderSetPieces(currentTeamPlan);return;}const player=e.target.closest('[data-set-piece-player]');if(player&&currentTeamPlan){const starters=await starterPlayers(currentTeamPlan);await ensureSetPieces(currentTeamPlan);currentSetPieceState=R.setManualSetPiece(currentSetPieceState,state.setPieceMode,player.dataset.setPiecePlayer,starters);await saveSetPieceState();await renderSetPieces(currentTeamPlan);toast(`${setPieceLabel(state.setPieceMode)} assigned manually`);return;}const clear=e.target.closest('#clearSetPieceBtn');if(clear&&currentTeamPlan){const starters=await starterPlayers(currentTeamPlan);await ensureSetPieces(currentTeamPlan);currentSetPieceState=R.setManualSetPiece(currentSetPieceState,state.setPieceMode,'',starters);await saveSetPieceState();await renderSetPieces(currentTeamPlan);toast(`${setPieceLabel(state.setPieceMode)} cleared`);return;}const refresh=e.target.closest('#refreshSetPiecesBtn');if(refresh&&currentTeamPlan){const starters=await starterPlayers(currentTeamPlan);await ensureSetPieces(currentTeamPlan);currentSetPieceState=R.refreshSetPieceRecommendations(currentSetPieceState,starters);await saveSetPieceState();await renderSetPieces(currentTeamPlan);toast('Set-piece recommendations refreshed');return;}const formationPlayer=e.target.closest('#formationPitch [data-player-key]');if(formationPlayer){state.playerKey=formationPlayer.dataset.playerKey;persistUiState();go('player');return;}const step=e.target.closest('[data-mentor-step]');if(step){const id=step.dataset.mentorId,input=document.querySelector(`[data-mentor-level="${CSS.escape(id)}"]`),next=await setMentorLevel(id,Number(input?.value||1)+Number(step.dataset.mentorStep||0));if(input)input.value=next;await updatePlanOnly();return;}});
